class Solution:
    def evalRPN(self, tokens: list[str]) -> int:
        stack: list[int] = []
        for i, token in enumerate(tokens):
            if token not in {"+", "-", "*", "/"}:
                stack.append(int(token))  # viz:push
                continue
            right = stack.pop()  # viz:pop
            left = stack.pop()
            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            else:
                result = int(left / right)  # viz:divide
            stack.append(result)  # viz:result
        return stack[0]  # viz:done
